package ru.reader.rsvp;
import android.app.Activity;
import android.os.Bundle;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.view.Gravity;
import android.view.View;
import android.widget.*;

/** Offline, short-form collapsible in-app manual. */
public class ActivityInfo extends NavigationActivity {
    private int bg,fg;
    private String targetSection="";
    private ScrollView scrollView;
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable background(int color){GradientDrawable gd=new GradientDrawable();gd.setColor(color);gd.setCornerRadius(dp(12));return gd;}
    TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(fg);return t;}
    @Override public void onCreate(Bundle state){super.onCreate(state);SharedPreferences prefs=getSharedPreferences("reader",0);
        bg=prefs.getInt("bg",0xfff3e7d5);fg=prefs.getInt("fg",0xff30221e);
        LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(bg);root.setPadding(dp(16),dp(22),dp(16),dp(12));setContentView(root);SafeSystemBars.matchBackground(this,bg);
        TextView title=text("☰   Справка",24);title.setPadding(dp(2),dp(8),0,dp(18));title.setOnClickListener(v->UniversalDrawer.show(this));root.addView(title);
        targetSection=getIntent().getStringExtra("help_section");
        if(targetSection==null)targetSection="";
        ScrollView scroll=new ScrollView(this);scrollView=scroll;
        root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout entries=new LinearLayout(this);entries.setOrientation(1);scroll.addView(entries);
        String customBody=getIntent().getStringExtra("help_body");
        if(customBody!=null&&!customBody.isEmpty()&&!targetSection.isEmpty()){
            section(entries,targetSection,customBody);
        }
        section(entries,"Библиотека","Добавляйте EPUB и FB2, открывайте последнюю книгу и управляйте обложками. Позиция чтения сохраняется автоматически.");
        section(entries,"Обычное чтение","Изменяйте оформление, шрифт и размер. Для перехода к чтению выберите книгу в библиотеке.");
        section(entries,"Скоростное чтение","Выбирайте режим показа слов, количество соседних слов и скорость. Воспроизведение ставится на паузу кнопкой Play.");
        section(entries,"Аудиокниги","Добавляйте папки MP3/M4A, выбирайте главы, скорость, обложку и таймер сна. Прогресс сохраняется раздельно для каждой книги.");
        section(entries,"Системные голоса TTS","Выбирайте установленные локальные голоса Samsung и Google, слушайте пример, настройте скорость в словах в минуту. Локальные звуковые файлы хранятся временно.");
        section(entries,"Microsoft Edge TTS","Для синтеза требуется интернет. Полученные фрагменты сохраняются постоянно и доступны повторно через «Файлы аудиокниги».");
        section(entries,"Офлайн-прослушивание","Скачанные онлайн-фрагменты доступны без сети. Если они кончились, приложение предложит продолжить через системный TTS.");
        section(entries,"Регулярные выражения словаря Edge TTS",
            "Словарь Edge TTS поддерживает обычные замены и регулярные выражения (Java Regex). " +
            "Откройте «Словарь Edge TTS», нажмите «+», включите «Регулярное выражение», " +
            "введите «Найти» и «Заменить на». Для удаления совпадения оставьте замену пустой " +
            "или используйте вкладку «Игнорировать». Перед сохранением нажмите «Проверить Regex / замену».\n\n" +
            "ОСНОВНЫЕ ОБОЗНАЧЕНИЯ\n" +
            ". — любой символ, кроме переноса строки\n" +
            "\\d — цифра; \\s — пробельный символ; \\b — граница слова\n" +
            "* — 0 или более повторений, + — 1 или более, ? — необязательный элемент\n" +
            "[ауи] — один символ из списка; (?:а|у|и) — один из вариантов\n" +
            "(...) — группа захвата; $1 — её подстановка; \\n — перевод строки\n" +
            "^ — начало, $ — конец строки (с (?m))\n" +
            "(?i) — без учёта регистра; (?iu) — Unicode-регистр; (?m) — многострочный поиск\n\n" +
            "ПРИМЕРЫ (НАЙТИ → ЗАМЕНИТЬ НА)\n" +
            "Формы «полка/полку/полки»: (?iu)\\bполк[ауи]\\b → полка\n" +
            "Сокращение «гл. 12»: (?iu)\\bгл\\.\\s*(\\d+) → глава $1\n" +
            "Пустые строки: (?m)^[ \\t]*\\r?\\n → [оставить пустым]\n" +
            "Звёздочка: \\* → [оставить пустым]\n\n" +
            "ВАЖНО: вводите обратные косые черты как показано в примерах. " +
            "Обычные правила не требуют Regex. Выражения изменяют только текст, отправляемый на озвучивание. " +
            "Исходная книга не меняется. Для подсветки сохраняется сопоставление исходных смещений; " +
            "сложные перестановки групп могут иметь неточное выравнивание. " +
            "Проверяйте правило на фрагменте книги, прежде чем использовать его для всей аудиокниги.");
        section(entries,"Скачать по ссылке",
            "Вводите по одной ссылке в строке. Поддерживаются MP3, FB2 и EPUB: прямые HTTPS-файлы, " +
            "публичные ссылки Яндекс.Диска, Dropbox и Google Drive, если доступна прямая загрузка. " +
            "Для Яндекс.Диска доступны первые 100 файлов публичной папки. Другие облака могут " +
            "потребовать отдельный адаптер.\n\n" +
            "Папку сохранения выбирайте иконкой папки справа в верхней панели. " +
            "Выберите файлы после анализа ссылок. Необязательная подпапка создаётся автоматически; " +
            "если её название оставить пустым, файлы попадут прямо в выбранную папку.");
        section(entries,"Поиск аудиокниг и манги",
            "Найдите произведение, выберите главы и запустите скачивание. " +
            "Иконка папки в верхней панели задаёт дополнительную папку для сохранения MP3 или CBZ. " +
            "Файлы также сохраняются во внутренней библиотеке приложения для чтения и воспроизведения. Каждый поисковик запоминает свою выбранную папку отдельно.");
        section(entries,"Цвет выделения","Единый цвет выделения для оглавления, манги, аудиокниг, словаря и диалогов. При варианте «Из текущей темы» используется цвет акцентных кнопок. В режиме «Настройка RGB вручную» можно задать цвет по каналам красного, зелёного и синего.");
        section(entries,"Загрузки","Просматривайте загрузки и используйте «Подготовить всю книгу», чтобы получить недостающие части аудио заранее. Для манги в меню трёх точек доступны просмотр папки внутри приложения, выбор томов для удаления и экспорт CBZ. Удаление не затрагивает другие серии. Внешние проводники Android могут не иметь доступа к закрытой папке приложения.");
        section(entries,"Чтейцо и награды","Читайте книги, развивайте питомца и получайте награды. В настройках доступен переключатель питомца.");
        section(entries,"Чтейцо — Рыбалка",
            "Рыбалка заменяет прежние мини-игры. Игра проходит внутри карточки Чтейца. " +
            "Нажмите и удерживайте палец в любом месте игрового поля: бегущий индикатор шкалы движется вверх-вниз. " +
            "Отпустите палец ближе к акцентной отметке 80%, чтобы забросить поплавок дальше. " +
            "После приводнения рыба сама не клюёт. Удерживайте палец для подтягивания поплавка к нижней границе: " +
            "случайная поклёвка возможна только во время движения с зажатым пальцем. " +
            "При отпускании подтягивание останавливается. Если поплавок достиг нижней границы, попытка заканчивается.\n\n" +
            "При поклёвке появляется вертикальная шкала: удерживание поднимает акцентную зону, отпускание опускает. " +
            "Если рыбка находится внутри зоны, прогресс ловли растёт, иначе утекает. Полная шкала означает поимку. " +
            "При срыве награды не начисляются.\n\n" +
            "Вся графика рыбалки — Android XML VectorDrawable и shape, включая рыб, поплавок, шкалы и маркеры. " +
            "Рыбка залита цветом редкости, целевая зона окрашена акцентным цветом темы.");
        section(entries,"Чтейцо — Рыбалка: редкость и награды",
            "Редкость рыбы: обычная — белая, необычная — зелёная, редкая — голубая, " +
            "легендарная — оранжевая, мифическая — фиолетовая. " +
            "Множители опыта и золота соответственно ×1, ×1,5, ×2,5, ×4 и ×7. " +
            "Масса случайна в диапазонах: 0,2–2; 0,5–3,5; 1–5; 2–8; 3–12 кг. " +
            "Дальний заброс повышает вероятность редких рыб, короткий преимущественно даёт обычных и необычных. " +
            "Шанс никогда не гарантирован.\n\n" +
            "За удачную поимку: опыт = масса в кг ×20×множитель; золото = масса в кг ×5×множитель " +
            "(с округлением и минимумом 1 золото). При срыве наград нет. " +
            "Один заброс расходует одну наживку независимо от результата.\n\n" +
            "10 наживок выдаётся за прочитанную главу, прослушанную главу или каждые 10 уникальных страниц манги. " +
            "Повторное чтение уже учтённых страниц или глав не даёт дублирующую награду. " +
            "Наживки покупаются за игровое золото: 1 за 30, 10 за 270 или 50 за 1200. " +
            "Новому игроку выдаётся 10 стартовых наживок. Покупки за реальные деньги отсутствуют.");
        section(entries,"Редактирование меню","Выключено: кнопка-карандаш. Включено: долгое нажатие на пустое место или заголовок.");
        section(entries,"Чтейцо — описание","Чтейцо — маленький спутник ваших книжных приключений. Ему нравятся истории, уютные минуты чтения и удивительные аудиопутешествия.\n\nСо временем питомец меняется и взрослеет. Ваши привычки могут сделать его особенным — какой сюрприз ждёт впереди, узнаете сами.\n\nПочаще заглядывайте к нему: ласковое прикосновение поднимает настроение, а книги помогают расти. Если долго не читать, питомец может мягко напомнить о себе.");
        section(entries,"Справка об озвучке","Режим «Озвучка» использует тот же текст и оглавление, что и остальные режимы. Выбор движка и голоса доступен в плеере озвучки.");
        section(entries,"Задержка старта","От 1 до 10 секунд. При Play появится прозрачный контурный круг без цифр: полная окружность постепенно исчезает по часовой стрелке.");
        section(entries,"Подсветка текста","0% — фон невидим, 100% — непрозрачная заливка. Применяется в озвучке и при выборе предложения.");
        section(entries,"Скоростное чтение — порции","Последовательно отображать или выделять от 1 до 4 слов. Книга уже разбивается на слова, поэтому изменение порции работает быстрее и без повторного анализа текста.");
        section(entries,"Скоростное чтение — фокус","Оптимальное место для фиксации взгляда при скорочтении. По умолчанию слово для старта выбирается касанием текста. Если включить настройку, прокрутка меняет выбранное слово. Панель слова и линий появляется только после Play.");
        section(entries,"Выбор слова","Кнопка выбора слова работает как переключатель: коснитесь её, затем выбирайте стартовое слово в тексте столько раз, сколько нужно. Фон у выделенного слова не используется.");
        section(entries,"Режим Курсор","В режиме «Курсор» слово можно выбирать касанием постоянно, без отдельного переключателя. По умолчанию размер слова не увеличивается: 100%. При выборе «Без цвета» фон или цвет текста не применяются.");
        section(entries,"Цвет обычных кнопок","Назад, закладки, настройки, нейтральные команды. Значок Ø — стандартный цвет темы.");
        section(entries,"Цвет акцентных кнопок","Play / Pause, выбор режима и другие основные действия. Значок Ø — стандартный цвет темы.");
        section(entries,"Обновления","Пункт «Обновление» в главном меню проверяет новую версию приложения.");
    }
    void section(LinearLayout entries,String heading,String body){
        LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setBackground(background((Color.red(bg)+Color.green(bg)+Color.blue(bg))<360?0xff353b3a:0xfffff8ee));
        LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(9);entries.addView(panel,lp);
        TextView h=text(heading+"    ▾",17);h.setPadding(dp(14),dp(16),dp(14),dp(16));panel.addView(h);
        TextView content=text(body,15);content.setPadding(dp(14),0,dp(14),dp(17));content.setVisibility(View.GONE);panel.addView(content);
        if(heading.equals(targetSection)){
            content.setVisibility(View.VISIBLE);h.setText(heading+"    ▴");
            scrollView.post(()->scrollView.smoothScrollTo(0,panel.getTop()));
        }
        h.setOnClickListener(v->{boolean show=content.getVisibility()!=View.VISIBLE;content.setVisibility(show?View.VISIBLE:View.GONE);h.setText(heading+(show?"    ▴":"    ▾"));});
    }
}
